    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        //
        // spot: fetchTicker, fetchTickers
        //
        //     {
        //         "symbol": "btc_usdt",
        //         "ticker": {
        //             "high": "29695.57",
        //             "vol": "6890.2789",
        //             "low": "29110",
        //             "change": "0.58",
        //             "turnover": "202769821.06",
        //             "latest": "29405.98"
        //         },
        //         "timestamp": :1692064274908
        //     }
        //
        // swap: fetchTickers
        //
        //     {
        //         "lastTime": 1784884932,
        //         "prePositionFeeRate": "0.000053",
        //         "volume": "2435.459",
        //         "symbol": "BTCUSDT",
        //         "highestPrice": "29446.5",
        //         "lowestPrice": "29362.9",
        //         "openPrice": "29419.5",
        //         "markedPrice": "29385.1",
        //         "turnover": "36345526.2438402",
        //         "lastPrice": "29387.0"
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object timestamp = this.safeInteger(ticker, "timestamp");
        if (Helpers.isTrue(Helpers.isEqual(timestamp, null)))
        {
            timestamp = this.safeTimestamp(ticker, "lastTime");
        }
        Object marketId = this.safeString(ticker, "symbol");
        Object symbol = this.safeSymbol(marketId, market);
        Object tickerData = this.safeValue(ticker, "ticker", new java.util.HashMap<String, Object>() {{}});
        market = this.safeMarket(marketId, market);
        Object data = ((Helpers.isTrue((Helpers.isEqual(Helpers.GetValue(market, "contract"), true))))) ? ticker : tickerData;
        final Object finalTimestamp = timestamp;
        return this.safeTicker(new java.util.HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", finalTimestamp );
            put( "datetime", Lbank.this.iso8601(finalTimestamp) );
            put( "high", Lbank.this.safeString2(data, "high", "highestPrice") );
            put( "low", Lbank.this.safeString2(data, "low", "lowestPrice") );
            put( "bid", null );
            put( "bidVolume", null );
            put( "ask", null );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", Lbank.this.safeString(data, "openPrice") );
            put( "close", null );
            put( "last", Lbank.this.safeString2(data, "latest", "lastPrice") );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", Lbank.this.safeString(data, "change") );
            put( "average", null );
            put( "baseVolume", Lbank.this.safeString2(data, "vol", "volume") );
            put( "quoteVolume", Lbank.this.safeString(data, "turnover") );
            put( "info", ticker );
        }}, market);
    }

    /**
     * @method
     * @name lbank#fetchTicker
     * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
     * @see https://www.lbank.com/en-US/docs/index.html#query-current-market-data-new
     * @param {string} symbol unified symbol of the market to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Ticker> fetchTicker(Object symbol, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            if (Helpers.isTrue(Helpers.isEqual(Helpers.GetValue(market, "swap"), true)))
            {
                Object responseForSwap = (this.fetchTickers( (Object) (new java.util.ArrayList<Object>(java.util.Arrays.asList(Helpers.GetValue(market, "symbol")))), (Object) (parameters))).join();
                return this.safeValue(responseForSwap, Helpers.GetValue(market, "symbol"));
            }
            Object request = new java.util.HashMap<String, Object>() {{
                put( "symbol", Helpers.GetValue(market, "id") );
            }};
            Object response = (this.spotPublicGetTicker24hr(this.extend(request, parameters))).join();
            //
            //     {
            //         "result": "true",
            //         "data": [
            //             {
            //                 "symbol": "btc_usdt",
            //                 "ticker": {
            //                     "high": "29695.57",
            //                     "vol": "6890.2789",
            //                     "low": "29110",
            //                     "change": "0.58",
            //                     "turnover": "202769821.06",
            //                     "latest": "29405.98"
            //                 },
            //                 "timestamp": :1692064274908
            //             }
            //         ],
            //         "error_code": 0,
            //         "ts": :1692064276872
            //     }
            //
            Object data = this.safeValue(response, "data", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            Object first = this.safeDict(data, 0, new java.util.HashMap<String, Object>() {{}});
            return this.parseTicker(first, market);
        }).thenApply(io.github.ccxt.TypedCores::toTicker);

    }

