    /**
     * @method
     * @name lbank#createOrder
     * @description create a trade order
     * @see https://www.lbank.com/en-US/docs/index.html#place-order
     * @see https://www.lbank.com/en-US/docs/index.html#place-an-order
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much of currency you want to trade in units of base currency
     * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Order> createOrder(Object symbol, Object type2, Object side2, Object amount, Object... optionalArgs)
    {
        final Object type3 = type2;
        final Object side3 = side2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object type = type3;
            Object side = side3;
            Object price = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            Object clientOrderId = this.safeString2(parameters, "custom_id", "clientOrderId");
            Object postOnly = this.safeBool(parameters, "postOnly", false);
            Object timeInForce = this.safeStringUpper(parameters, "timeInForce");
            parameters = this.omit(parameters, new java.util.ArrayList<Object>(java.util.Arrays.asList("custom_id", "clientOrderId", "timeInForce", "postOnly")));
            Object request = new java.util.HashMap<String, Object>() {{
                put( "symbol", Helpers.GetValue(market, "id") );
            }};
            Object ioc = (Helpers.isEqual(timeInForce, "IOC"));
            Object fok = (Helpers.isEqual(timeInForce, "FOK"));
            Object maker = (Helpers.isTrue((Helpers.isEqual(postOnly, true))) || Helpers.isTrue((Helpers.isEqual(timeInForce, "PO"))));
            if (Helpers.isTrue(Helpers.isTrue((Helpers.isEqual(type, "market"))) && Helpers.isTrue((Helpers.isTrue(Helpers.isTrue(ioc) || Helpers.isTrue(fok)) || Helpers.isTrue(maker)))))
            {
                throw new InvalidOrder((String)Helpers.add(this.id, " createOrder () does not allow market FOK, IOC, or postOnly orders. Only limit IOC, FOK, and postOnly orders are allowed")) ;
            }
            if (Helpers.isTrue(Helpers.isEqual(type, "limit")))
            {
                Helpers.addElementToObject(request, "type", side);
                Helpers.addElementToObject(request, "price", this.priceToPrecision(symbol, price));
                Helpers.addElementToObject(request, "amount", this.amountToPrecision(symbol, amount));
                if (Helpers.isTrue(ioc))
                {
                    Helpers.addElementToObject(request, "type", Helpers.add(Helpers.add(side, "_"), "ioc"));
                } else if (Helpers.isTrue(fok))
                {
                    Helpers.addElementToObject(request, "type", Helpers.add(Helpers.add(side, "_"), "fok"));
                } else if (Helpers.isTrue(maker))
                {
                    Helpers.addElementToObject(request, "type", Helpers.add(Helpers.add(side, "_"), "maker"));
                }
            } else if (Helpers.isTrue(Helpers.isEqual(type, "market")))
            {
                if (Helpers.isTrue(Helpers.isEqual(side, "sell")))
                {
                    Helpers.addElementToObject(request, "type", Helpers.add(Helpers.add(side, "_"), "market"));
                    Helpers.addElementToObject(request, "amount", this.amountToPrecision(symbol, amount));
                } else if (Helpers.isTrue(Helpers.isEqual(side, "buy")))
                {
                    Helpers.addElementToObject(request, "type", Helpers.add(Helpers.add(side, "_"), "market"));
                    Object quoteAmount = null;
                    Object createMarketBuyOrderRequiresPrice = true;
                    var createMarketBuyOrderRequiresPriceparametersVariable = this.handleOptionAndParams(parameters, "createOrder", "createMarketBuyOrderRequiresPrice", true);
                    createMarketBuyOrderRequiresPrice = ((java.util.List<Object>) createMarketBuyOrderRequiresPriceparametersVariable).get(0);
                    parameters = ((java.util.List<Object>) createMarketBuyOrderRequiresPriceparametersVariable).get(1);
                    Object cost = this.safeNumber(parameters, "cost");
                    parameters = this.omit(parameters, "cost");
                    if (Helpers.isTrue(!Helpers.isEqual(cost, null)))
                    {
                        quoteAmount = this.costToPrecision(symbol, cost);
                    } else if (Helpers.isTrue(createMarketBuyOrderRequiresPrice))
                    {
                        if (Helpers.isTrue(Helpers.isEqual(price, null)))
                        {
                            throw new InvalidOrder((String)Helpers.add(this.id, " createOrder() requires the price argument for market buy orders to calculate the total cost to spend (amount * price), alternatively set the createMarketBuyOrderRequiresPrice option or param to false and pass the cost to spend in the amount argument")) ;
                        } else
                        {
                            Object amountString = this.numberToString(amount);
                            Object priceString = this.numberToString(price);
                            Object costRequest = Precise.stringMul(amountString, priceString);
                            quoteAmount = this.costToPrecision(symbol, costRequest);
                        }
                    } else
                    {
                        quoteAmount = this.costToPrecision(symbol, amount);
                    }
                    // market buys require filling the price param instead of the amount param, for market buys the price is treated as the cost by lbank
                    Helpers.addElementToObject(request, "price", quoteAmount);
                }
            }
            if (Helpers.isTrue(!Helpers.isEqual(clientOrderId, null)))
            {
                Helpers.addElementToObject(request, "custom_id", clientOrderId);
            }
            Object options = this.safeValue(this.options, "createOrder", new java.util.HashMap<String, Object>() {{}});
            Object defaultMethod = this.safeString(options, "method", "spotPrivatePostSupplementCreateOrder");
            Object method = this.safeString(parameters, "method", defaultMethod);
            parameters = this.omit(parameters, "method");
            Object response = null;
            if (Helpers.isTrue(Helpers.isEqual(method, "spotPrivatePostCreateOrder")))
            {
                response = (this.spotPrivatePostCreateOrder(this.extend(request, parameters))).join();
            } else
            {
                response = (this.spotPrivatePostSupplementCreateOrder(this.extend(request, parameters))).join();
            }
            //
            //      {
            //          "result":true,
            //          "data":{
            //              "symbol":"doge_usdt",
            //              "order_id":"0cf8a3de-4597-4296-af45-be7abaa06b07"
            //              },
            //          "error_code":0,
            //          "ts":1648162321043
            //      }
            //
            Object result = this.safeValue(response, "data", new java.util.HashMap<String, Object>() {{}});
            return this.safeOrder(new java.util.HashMap<String, Object>() {{
                put( "id", Lbank.this.safeString(result, "order_id") );
                put( "info", result );
            }}, market);
        }).thenApply(io.github.ccxt.TypedCores::toOrder);

    }

    public Object parseOrderStatus(Object status)
    {
        Object statuses = new java.util.HashMap<String, Object>() {{
            put( "-1", "canceled" );
            put( "0", "open" );
            put( "1", "open" );
            put( "2", "closed" );
            put( "3", "canceled" );
            put( "4", "closed" );
        }};
        return this.safeString(statuses, ((String)status), status);
    }

    public Object parseOrder(Object order, Object... optionalArgs)
    {
        //
        // fetchOrderSupplement (private)
        //
        //      {
        //          "cummulativeQuoteQty":0,
        //          "symbol":"doge_usdt",
        //          "executedQty":0,
        //          "orderId":"53d2d53e-70fb-4398-b722-f48571a5f61e",
        //          "origQty":1E+2,
        //          "price":0.05,
        //          "clientOrderId":null,
        //          "origQuoteOrderQty":5,
        //          "updateTime":1648163406000,
        //          "time":1648163139387,
        //          "type":"buy_maker",
        //          "status":-1
        //      }
        //
        //
        // fetchOrderDefault (private)
        //
        //      {
        //          "symbol":"shib_usdt",
        //          "amount":1,
        //          "create_time":1649367863356,
        //          "price":0.0000246103,
        //          "avg_price":0.00002466180000000104,
        //          "type":"buy_market",
        //          "order_id":"abe8b92d-86d9-4d6d-b71e-d14f5fb53ddf",
        //          "custom_id": "007",                                 // field only present if user creates it at order time
        //          "deal_amount":40548.54065802,
        //          "status":2
        //      }
        //
        // fetchOpenOrders (private)
        //
        //      {
        //          "cummulativeQuoteQty":0,
        //          "symbol":"doge_usdt",
        //          "executedQty":0,
        //          "orderId":"73878edf-008d-4e4c-8041-df1f1b2cd8bb",
        //          "origQty":100,
        //          "price":0.05,
        //          "origQuoteOrderQty":5,
        //          "updateTime":1648501762000,
        //          "time":1648501762353,
        //          "type":"buy",
        //          "status":0
        //      }
        //
        // fetchOrders (private)
        //
        //      {
        //          "cummulativeQuoteQty":0,
        //          "symbol":"doge_usdt",
        //          "executedQty":0,
        //          "orderId":"2cadc7cc-b5f6-486b-a5b4-d6ac49a9c186",
        //          "origQty":100,
        //          "price":0.05,
        //          "origQuoteOrderQty":5,
        //          "updateTime":1648501384000,
        //          "time":1648501363889,
        //          "type":"buy",
        //          "status":-1
        //      }
        //
        // cancelOrder
        //
        //    {
        //        "executedQty":0.0,
        //        "price":0.05,
        //        "origQty":100.0,
        //        "tradeType":"buy",
        //        "status":0
        //    }
        //
        // cancelAllOrders
        //
        //    {
        //        "executedQty":0.00000000000000000000,
        //        "orderId":"293ef71b-3e67-4962-af93-aa06990a045f",
        //        "price":0.05000000000000000000,
        //        "origQty":100.00000000000000000000,
        //        "tradeType":"buy",
        //        "status":0
        //    }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object id = this.safeString2(order, "orderId", "order_id");
        Object clientOrderId = this.safeString2(order, "clientOrderId", "custom_id");
        Object timestamp = this.safeInteger2(order, "time", "create_time");
        Object rawStatus = this.safeString(order, "status");
        Object marketId = this.safeString(order, "symbol");
        market = this.safeMarket(marketId, market);
        Object timeInForce = null;
        Object postOnly = false;
        Object type = "limit";
        Object rawType = this.safeString2(order, "type", "tradeType"); // buy, sell, buy_market, sell_market, buy_maker,sell_maker,buy_ioc,sell_ioc, buy_fok, sell_fok
        Object parts = Helpers.split(((String)rawType), "_");
        Object side = this.safeString(parts, 0);
        Object typePart = this.safeString(parts, 1); // market, maker, ioc, fok or undefined (limit)
        if (Helpers.isTrue(Helpers.isEqual(typePart, "market")))
        {
            type = "market";
        }
        if (Helpers.isTrue(Helpers.isEqual(typePart, "maker")))
        {
            postOnly = true;
            timeInForce = "PO";
        }
        if (Helpers.isTrue(Helpers.isEqual(typePart, "ioc")))
        {
            timeInForce = "IOC";
        }
        if (Helpers.isTrue(Helpers.isEqual(typePart, "fok")))
        {
            timeInForce = "FOK";
        }
        Object price = this.safeString(order, "price");
        Object costString = this.safeString(order, "cummulativeQuoteQty");
        Object amountString = null;
        if (Helpers.isTrue(!Helpers.isEqual(rawType, "buy_market")))
        {
            amountString = this.safeString2(order, "origQty", "amount");
        }
        Object filledString = this.safeString2(order, "executedQty", "deal_amount");
        final Object finalMarket = market;
        final Object finalType = type;
        final Object finalTimeInForce = timeInForce;
        final Object finalPostOnly = postOnly;
        final Object finalAmountString = amountString;
        return this.safeOrder(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "clientOrderId", clientOrderId );
            put( "datetime", Lbank.this.iso8601(timestamp) );
            put( "timestamp", timestamp );
            put( "lastTradeTimestamp", null );
            put( "status", Lbank.this.parseOrderStatus(rawStatus) );
            put( "symbol", Helpers.GetValue(finalMarket, "symbol") );
            put( "type", finalType );
            put( "timeInForce", finalTimeInForce );
            put( "postOnly", finalPostOnly );
            put( "side", side );
            put( "price", price );
            put( "triggerPrice", null );
            put( "cost", costString );
            put( "amount", finalAmountString );
            put( "filled", filledString );
            put( "remaining", null );
            put( "trades", null );
            put( "fee", null );
            put( "info", order );
            put( "average", null );
        }}, market);
    }

    /**
     * @method
     * @name lbank#fetchOrder
     * @description fetches information on an order made by the user
     * @see https://www.lbank.com/en-US/docs/index.html#query-order
     * @see https://www.lbank.com/en-US/docs/index.html#query-order-new
     * @param {string} id order id
     * @param {string} symbol unified symbol of the market the order was made in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Order> fetchOrder(Object id, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbol = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object method = this.safeString(parameters, "method");
            if (Helpers.isTrue(Helpers.isEqual(method, null)))
            {
                Object options = this.safeValue(this.options, "fetchOrder", new java.util.HashMap<String, Object>() {{}});
                method = this.safeString(options, "method", "fetchOrderSupplement");
            }
            if (Helpers.isTrue(Helpers.isEqual(method, "fetchOrderSupplement")))
            {
                return (this.fetchOrderSupplement(id, symbol, parameters)).join();
            }
            return (this.fetchOrderDefault(id, symbol, parameters)).join();
        }).thenApply(io.github.ccxt.TypedCores::toOrder);

    }

